<script setup lang="ts">
import {ref,computed,watch} from 'vue'
import AppShell from '../components/AppShell.vue'
import PrivateImage from '../components/PrivateImage.vue'
import PointBalance from '../components/PointBalance.vue'
import MediaUploader from '../components/MediaUploader.vue'
import StatusPill from '../components/StatusPill.vue'
import EmptyState from '../components/EmptyState.vue'
import LoadMore from '../components/LoadMore.vue'
import {usePage} from '../composables/usePage'
import {get,getAll,mutate,familyPath,childPath} from '../services/api'
import {go} from '../services/navigation'
import {label,dateTime,businessDate,daysAgo,toUtc,now,unit,integer,displayOperator} from '../services/format'
import {mediaUrl,previewMedia} from '../services/media'
import type {Dashboard,Today,Plan,PlanInput,PlanVersion,Occurrence,Child,Order,PageResult,UploadItem,Submission} from '../services/types'
const props=defineProps<{page:string;query:Record<string,string>}>();const childPage=['today','activity'].includes(props.page)
const dashboard=ref<Dashboard|null>(null),today=ref<Today|null>(null),plans=ref<Plan[]>([]),plan=ref<Plan|null>(null),occurrences=ref<Occurrence[]>([]),occurrence=ref<Occurrence|null>(null),versions=ref<PlanVersion[]>([]),children=ref<Child[]>([]),todos=ref<Array<Occurrence|Order>>([]),type=ref('ROUTINE'),todoType=ref(props.query.type||'REVIEW'),status=ref(''),childId=ref(props.query.childId||''),date=ref(props.query.date||businessDate()),cursor=ref<string|null>(null),hasMore=ref(false),note=ref(''),count=ref(''),checked=ref(false),photos=ref<UploadItem[]>([]),reason=ref(''),action=ref(''),saved=ref(false),completedDate=ref(businessDate()),completedTime=ref('18:00'),draftVersion=ref(0),startPolicy=ref('TOMORROW'),copyTitle=ref(''),displayDescription=ref('')
const form=ref({type:'ROUTINE' as 'ROUTINE'|'CHALLENGE',title:'',description:'',metric:'CHECK',targetValue:'',unit:'REP',awardPoints:'5',childIds:[] as string[],weekdays:[1,2,3,4,5,6,7],startDate:businessDate(),startTime:'08:00',endDate:daysAgo(-1),endTime:'20:00'})
const metrics=['CHECK','COUNT','DURATION','DISTANCE'];const weekdays=['周一','周二','周三','周四','周五','周六','周日'];const titles:Record<string,string>={home:'今天也慢慢来',todos:'把努力接住',plans:'我们的计划',planEdit:props.query.id?'编辑家庭约定':'从一件小事开始',plan:'计划与完成情况',occurrence:'确认孩子的努力',today:'今天想完成哪件小事？',activity:'完成记录'}
const {loading,error,busy,reload,act,session}=usePage(props.page,load,childPage?'child':'guardian')
let hydratingDraft=false
function localDraftKey(){return occurrence.value&&session.view?'pointjoy.completion-input.'+session.view.actorScopeKey+'.'+occurrence.value.id:''}
function persistLocalDraft(){const k=localDraftKey();if(!k||hydratingDraft||!['OPEN','NEEDS_CHANGES'].includes(occurrence.value!.status))return;uni.setStorageSync(k,{version:occurrence.value!.version,count:count.value,checked:checked.value,note:note.value,updatedAt:Date.now()});saved.value=false}
watch([count,checked,note],persistLocalDraft,{flush:'sync'})
function restoreLocalDraft(){const k=localDraftKey();if(!k)return;const input=uni.getStorageSync(k);if(input&&input.version===occurrence.value!.version&&Date.now()-input.updatedAt<86400000){count.value=input.count;checked.value=input.checked;note.value=input.note;saved.value=false}else if(input)uni.removeStorageSync(k)}
function clearLocalDraft(){const k=localDraftKey();if(k)uni.removeStorageSync(k)}
const snapshot=computed(()=>occurrence.value?.snapshot)
const editable=computed(()=>{const o=occurrence.value;if(!o)return false;if(o.status==='NEEDS_CHANGES')return now()<Date.parse(o.supplementUntil||o.endsAt);return o.status==='OPEN'&&now()>=Date.parse(o.startsAt)&&now()<Date.parse(o.endsAt)&&!['STOPPED','NOT_STARTED'].includes(o.displayState)})
const targetMax=computed(()=>snapshot.value?.metric==='DURATION'?1440:snapshot.value?.metric==='DISTANCE'?1000000:100000)
async function load(){
 if(['plans','planEdit','plan','home','todos'].includes(props.page)){children.value=await getAll<Child>(familyPath('/children'),{status:'ACTIVE'})}
 if(props.page==='home'){dashboard.value=await get<Dashboard>(familyPath('/dashboard'));return}
 if(props.page==='today'){today.value=await get<Today>(childPath(undefined,'/today'));return}
 if(props.page==='todos'){await loadTodos();return}
 if(props.page==='plans'){await loadPlans();return}
 if(props.page==='planEdit'&&props.query.id){plan.value=await get<Plan>(familyPath(`/plans/${props.query.id}`));const v=plan.value.scheduledVersion||plan.value.currentVersion||plan.value.draftVersion;if(v){form.value={type:plan.value.type,title:v.title,description:v.description||'',metric:v.metric,targetValue:v.targetValue===undefined?'':String(v.targetValue),unit:v.unit||'REP',awardPoints:String(v.awardPoints),childIds:v.childIds||plan.value.applicableChildIds,weekdays:v.weekdays||[1,2,3,4,5,6,7],startDate:v.startsAt?businessDate(v.startsAt):businessDate(),startTime:v.startsAt?dateTime(v.startsAt).slice(-5):'08:00',endDate:v.endsAt?businessDate(v.endsAt):daysAgo(-1),endTime:v.endsAt?dateTime(v.endsAt).slice(-5):'20:00'}}return}
 if(props.page==='plan'){plan.value=await get<Plan>(familyPath(`/plans/${props.query.id}`));displayDescription.value=plan.value.displayDescription||'';copyTitle.value=((plan.value.currentVersion||plan.value.draftVersion)?.title||'计划')+'（新约定）';await loadOccurrences();const v=await get<PageResult<PlanVersion>>(familyPath(`/plans/${props.query.id}/versions`));versions.value=v.items;return}
 if(['occurrence','activity'].includes(props.page)){hydratingDraft=true;occurrence.value=await get<Occurrence>(familyPath(`/occurrences/${props.query.id}`));const o=occurrence.value;const draft=o.draft;count.value=String(draft?.actualValue??o.latestSubmission?.actualValue??'');checked.value=draft?.checked??o.latestSubmission?.checked??false;note.value=draft?.note??o.latestSubmission?.note??'';draftVersion.value=draft?.version||0;const media=draft?.media||o.latestSubmission?.media||[];photos.value=media.map(m=>({localId:m.id,mediaId:m.id,status:m.status,progress:100,asset:m}));if(draft?.mediaIds&&!media.length)photos.value=await Promise.all(draft.mediaIds.map(async id=>{try{const asset=await get<import('../services/types').MediaAsset>(`/media/${id}`);return{localId:id,mediaId:id,status:asset.status,progress:100,asset}}catch{return{localId:id,mediaId:id,status:'DELETED' as const,progress:0,error:'草稿图片已过期，请重新选择'}}}));completedDate.value=o.businessDate||businessDate(o.startsAt);completedTime.value=businessDate()===completedDate.value?dateTime(new Date(now()).toISOString()).slice(-5):'18:00';restoreLocalDraft();hydratingDraft=false}
}
async function loadPlans(more=false){const result=await get<PageResult<Plan>>(familyPath('/plans'),{type:type.value,lifecycle:status.value||undefined,childId:childId.value||undefined,cursor:more?cursor.value:undefined});plans.value=more?[...plans.value,...result.items]:result.items;cursor.value=result.nextCursor||null;hasMore.value=result.hasMore}
async function loadTodos(more=false){const result=await get<PageResult<Occurrence|Order>>(familyPath('/todos'),{type:todoType.value,childId:childId.value||undefined,cursor:more?cursor.value:undefined});todos.value=more?[...todos.value,...result.items]:result.items;cursor.value=result.nextCursor||null;hasMore.value=result.hasMore}
async function loadOccurrences(more=false){if(date.value>businessDate()){const result=await get<{items?:Occurrence[]}>(familyPath(`/plans/${props.query.id}/schedule-preview`),{dateFrom:date.value,dateTo:date.value,childId:childId.value||undefined});occurrences.value=result.items||[];hasMore.value=false;return}const result=await get<PageResult<Occurrence>>(familyPath(`/plans/${props.query.id}/occurrences`),{dateFrom:plan.value?.type==='ROUTINE'?date.value:undefined,dateTo:plan.value?.type==='ROUTINE'?date.value:undefined,childId:childId.value||undefined,cursor:more?cursor.value:undefined});occurrences.value=more?[...occurrences.value,...result.items]:result.items;cursor.value=result.nextCursor||null;hasMore.value=result.hasMore}
function toggleChild(id:string){const ids=form.value.childIds;form.value.childIds=ids.includes(id)?ids.filter(x=>x!==id):[...ids,id]}
function toggleDay(day:number){form.value.weekdays=form.value.weekdays.includes(day)?form.value.weekdays.filter(x=>x!==day):[...form.value.weekdays,day].sort()}
function planInput():PlanInput{const f=form.value;if([...f.title.trim()].length<2||[...f.title.trim()].length>40)throw new Error('计划名称需2—40字');if(!integer(f.awardPoints,1,1000))throw new Error('奖励积分需为1—1,000整数');if(!f.childIds.length)throw new Error('请选择至少一位适用孩子');const max=f.metric==='DURATION'?1440:f.metric==='DISTANCE'?1000000:100000;if(f.metric!=='CHECK'&&!integer(f.targetValue,1,max))throw new Error(`目标需为1—${max}的整数`);if(f.type==='ROUTINE'&&!f.weekdays.length)throw new Error('请至少选择一个星期中的日期');const body:PlanInput={type:f.type,title:f.title.trim(),description:f.description.trim(),metric:f.metric as PlanInput['metric'],awardPoints:Number(f.awardPoints),childIds:f.childIds,...(f.metric!=='CHECK'?{targetValue:Number(f.targetValue),unit:f.metric==='COUNT'?f.unit:f.metric==='DURATION'?'MINUTE':'METER'}:{}),...(f.type==='ROUTINE'?{weekdays:f.weekdays}:{startsAt:toUtc(f.startDate,f.startTime),endsAt:toUtc(f.endDate,f.endTime)})};if(body.endsAt&&body.startsAt&&Date.parse(body.endsAt)<=Math.max(Date.parse(body.startsAt),now()))throw new Error('挑战结束时间必须晚于开始和当前时间');return body}
async function savePlan(publish=false){await act(async()=>{const input=planInput();let savedPlan:Plan;if(plan.value&&plan.value.lifecycle!=='DRAFT'){if(plan.value.type==='CHALLENGE')throw new Error('已发布挑战的要求冻结，只能修改展示说明或复制新挑战');savedPlan=await mutate<Plan>('POST',familyPath(`/plans/${plan.value.id}/revisions`),{...input,expectedVersion:plan.value.version},'修改明日起的日常')}else{savedPlan=await mutate<Plan>(plan.value?'PATCH':'POST',plan.value?familyPath(`/plans/${plan.value.id}`):familyPath('/plans'),{...input,...(plan.value?{expectedVersion:plan.value.version}:{})},'保存计划草稿');if(publish)savedPlan=await mutate<Plan>('POST',familyPath(`/plans/${savedPlan.id}/publish`),{expectedVersion:savedPlan.version,...(input.type==='ROUTINE'?{startPolicy:startPolicy.value}:{})},'发布家庭计划')}go('plan',{id:savedPlan.id},true)},'计划已保存')}
async function planAction(next:string){await act(async()=>{const p=plan.value!;if(next==='stop'&&!reason.value.trim())throw new Error('请填写停止原因');const accepted=await new Promise<boolean>(resolve=>uni.showModal({title:next==='stop'?'停止这次挑战':'确认计划变更',content:next==='stop'?'立即阻止尚未提交的新提交；已提交仍可审核，已获补充期限保留，已得积分不撤销。':next==='copy'?'会创建一份新草稿，发布后是新的可获奖机会。':'日常变更明天起生效，今天仍按原约定。',success:r=>resolve(r.confirm)}));if(!accepted)return;const result=await mutate<Plan>('POST',familyPath(`/plans/${p.id}/${next}`),{expectedVersion:p.version,...(next==='stop'?{reason:reason.value.trim()}:{}),...(next==='copy'?{newTitle:copyTitle.value.trim()||'新的家庭约定'}:{}),...(next==='publish'&&p.type==='ROUTINE'?{startPolicy:startPolicy.value}:{})},'修改计划状态');if(next==='copy')go('planEdit',{id:result.id});else await load()})}
async function saveDescription(){await act(async()=>{await mutate('PATCH',familyPath(`/plans/${plan.value!.id}/display-description`),{description:displayDescription.value,expectedVersion:plan.value!.version},'修改挑战展示说明');await load()},'展示说明已更新')}
function completionInput(goal:boolean){const s=snapshot.value!;if(s.metric==='CHECK'){if(goal&&!checked.value)throw new Error('请确认已经实际完成');return{checked:checked.value,note:note.value.trim(),mediaIds:photos.value.filter(p=>p.status==='READY'&&p.mediaId).map(p=>p.mediaId!)}}if(!integer(count.value,0,targetMax.value))throw new Error(`请填写0—${targetMax.value}之间的整数`);if(goal&&Number(count.value)<(s.targetValue||1))throw new Error('还没有达到约定目标，可以先保存草稿');return{actualValue:Number(count.value),note:note.value.trim(),mediaIds:photos.value.filter(p=>p.status==='READY'&&p.mediaId).map(p=>p.mediaId!)}}
async function submit(direct=false){await act(async()=>{if(photos.value.some(p=>p.status!=='READY'))throw new Error('请等待照片处理完成，失败照片可重试或移除');const body=completionInput(true);await mutate('POST',familyPath(`/occurrences/${occurrence.value!.id}/${direct?'direct-completion':'submissions'}`),{...body,expectedVersion:occurrence.value!.version,...(direct?{completedAt:toUtc(completedDate.value,completedTime.value)}:{})},direct?'直接记录真实完成':'提交给家长确认');clearLocalDraft();await load();saved.value=false},direct?'真实完成已记录并加分':'已经告诉家长，确认后积分会到账')}
async function saveDraft(){await act(async()=>{const body=completionInput(false);const result=await mutate<{draft:{version:number};occurrenceVersion:number}>('PUT',familyPath(`/occurrences/${occurrence.value!.id}/draft`),{...body,expectedOccurrenceVersion:occurrence.value!.version,expectedDraftVersion:draftVersion.value},'保存完成草稿');draftVersion.value=result.draft.version;occurrence.value!.version=result.occurrenceVersion;clearLocalDraft();saved.value=true},'草稿已保存，没有提交或加分')}
async function review(decision:'APPROVE'|'RETURN'|'EXEMPT'){await act(async()=>{if(decision!=='APPROVE'&&!reason.value.trim())throw new Error('请填写原因');const o=occurrence.value!;await mutate('POST',familyPath(`/occurrences/${o.id}/${decision==='EXEMPT'?'exemption':'review'}`),{expectedVersion:o.version,...(decision==='EXEMPT'?{reason:reason.value.trim()}:{decision,...(reason.value.trim()?{reason:reason.value.trim()}:{})})},decision==='APPROVE'?'通过并发放积分':decision==='RETURN'?'请孩子补充':'本次免做');action.value='';await load()},'记录已更新')}
function openTodo(item:Occurrence|Order){'snapshot'in item?go('occurrence',{id:item.id}):go('order',{id:item.id})}
function todoTitle(item:Occurrence|Order){return 'snapshot'in item?item.snapshot.title:item.rewardSnapshot.name||'兑换奖励'}
function todayRows(){return [...(today.value?.routines||[]),...(today.value?.challenges||[])]}
function completedFraction(progress?:{approvedCount?:number;expectedCount?:number;approved?:number;required?:number;numerator?:number;denominator?:number}){return`${progress?.approvedCount??progress?.approved??progress?.numerator??0} / ${progress?.expectedCount??progress?.required??progress?.denominator??0}`}
async function showPhotos(sub:Submission){await act(()=>previewMedia(sub.media.filter(m=>m.status!=='DELETED').map(m=>m.id)))}
</script>
<template><AppShell :title="titles[page]" :tab="page==='home'?'home':page==='plans'?'plans':page==='today'?'today':''" :back="!['home','plans','today'].includes(page)" :loading="loading" :error="error" @retry="reload">
<template v-if="page==='home'&&dashboard"><text class="caption">{{businessDate()}} · 北京时间</text><view class="grid3 section"><button class="stat" @tap="go('todos',{type:'REVIEW'})"><text class="stat-label">完成待审核</text><text class="stat-value">{{dashboard.pendingReviewCount}}</text><text class="caption">确认努力 →</text></button><button class="stat" @tap="go('todos',{type:'APPROVAL'})"><text class="stat-label">兑换待批准</text><text class="stat-value">{{dashboard.pendingApprovalCount}}</text><text class="caption">商量奖励 →</text></button><button class="stat" @tap="go('todos',{type:'FULFILLMENT'})"><text class="stat-label">奖励待兑现</text><text class="stat-value">{{dashboard.readyCount}}</text><text class="caption">兑现承诺 →</text></button></view><view class="section-head"><text class="section-title">孩子的今天</text><button class="text-button" @tap="go('family')">全部孩子 →</button></view><view v-for="c in dashboard.childrenSummary" :key="c.id" class="card"><view class="row" @tap="go('child',{id:c.id})"><PrivateImage :media-id="c.avatarMediaId" avatar/><view class="grow"><text class="card-title">{{c.nickname}}</text><text class="caption">日常已通过 {{completedFraction(c.routineProgress)}}</text></view><text class="points">{{c.account?.availablePoints??c.availablePoints??'—'}}积分</text></view><view class="button-row"><button class="secondary" @tap="go('history',{childId:c.id,record:'true'})">记录完成</button><button class="secondary" @tap="act(()=>session.enterChild(c.id))">孩子模式</button></view></view><EmptyState v-if="!dashboard.childrenSummary.length" title="添加第一位小朋友" description="先上传头像建立档案，再一起约定日常活动。"><button class="primary section" @tap="go('childEdit')">添加孩子</button></EmptyState><view class="hero section"><text class="card-title">把小事说清楚，把承诺记住。</text><text class="hero-copy">家长可以代录、审核并兑现。今天休息不会扣分。</text></view></template>
<template v-else-if="page==='today'&&today"><PointBalance :account="today.account"/><view class="section-head"><text class="section-title">今天的约定</text><text class="caption">日常 {{completedFraction(today.routineProgress)}} 已完成</text></view><view v-for="o in todayRows()" :key="o.id" class="card"><view class="row"><view class="art">{{o.snapshot.metric==='CHECK'?'✓':'↟'}}</view><view class="grow"><text class="caption">{{label(o.type)}}{{o.type==='CHALLENGE'?' · '+dateTime(o.endsAt)+'前':''}}</text><text class="card-title">{{o.snapshot.title}}</text><text class="caption">{{o.snapshot.metric==='CHECK'?'按约定完成':`${o.snapshot.targetValue}${unit(o.snapshot.metric,o.snapshot.unit)}`}}</text></view><text class="points">+{{o.snapshot.awardPoints}}</text></view><view class="divider"/><view class="row between"><StatusPill :status="o.displayState||o.status"/><button class="text-button" @tap="go('activity',{id:o.id})">{{o.status==='OPEN'?'我完成了':o.status==='NEEDS_CHANGES'?'去补充':'查看记录'}} →</button></view></view><EmptyState v-if="!todayRows().length" title="今天还没有安排" description="和家长一起商量一件想做的小事，也可以好好休息。"/><button class="secondary full section" @tap="go('wishes',{},true)">看看我的心愿</button></template>
<template v-else-if="page==='todos'"><view class="tabs"><button v-for="t in ['REVIEW','APPROVAL','FULFILLMENT']" :key="t" :class="{active:todoType===t}" @tap="todoType=t;act(()=>loadTodos())">{{t==='REVIEW'?'完成审核':t==='APPROVAL'?'兑换批准':'奖励兑现'}}</button></view><view v-if="children.length" class="field"><picker :range="['全部孩子',...children.map(c=>c.nickname)]" @change="childId=children[Number($event.detail.value)-1]?.id||'';act(()=>loadTodos())"><view class="select-control">{{children.find(c=>c.id===childId)?.nickname||'全部孩子'}}</view></picker></view><view v-for="item in todos" :key="item.id" class="card" @tap="openTodo(item)"><view class="row between"><text class="card-title">{{todoTitle(item)}}</text><StatusPill :status="item.status"/></view><text class="caption">{{item.child?.nickname||item.childNickname||'孩子记录'}}</text><text class="caption">{{'snapshot'in item?item.businessDate:'批准截止 '+dateTime(item.approvalExpiresAt)}}</text><button class="text-button">查看并处理 →</button></view><EmptyState v-if="!todos.length&&!loading" title="这一类待办都处理好了" description="也可以切换查看另外两类待办。"/><LoadMore :has-more="hasMore" :loading="busy" @more="act(()=>loadTodos(true))"/></template>
<template v-else-if="page==='plans'"><view class="section-head"><view class="tabs grow"><button :class="{active:type==='ROUTINE'}" @tap="type='ROUTINE';act(()=>loadPlans())">日常</button><button :class="{active:type==='CHALLENGE'}" @tap="type='CHALLENGE';act(()=>loadPlans())">一次挑战</button></view><button v-if="!session.isFamilyReadOnly" class="text-button" @tap="go('planEdit')">＋ 新建</button></view><view class="chip-row"><button v-for="s in (type==='ROUTINE'?['','DRAFT','PUBLISHED']:['','DRAFT','PUBLISHED','STOPPED'])" :key="s||'all'" class="chip" :class="{active:status===s}" @tap="status=s;act(()=>loadPlans())">{{s?label(s):'全部'}}</button></view><view v-for="p in plans" :key="p.id" class="card" @tap="go('plan',{id:p.id})"><view class="row between"><text class="card-title">{{(p.currentVersion||p.scheduledVersion||p.draftVersion)?.title||p.title||'计划草稿'}}</text><StatusPill :status="p.currentVersion?.active===false?'PAUSED':p.lifecycle"/></view><text class="caption">{{label(p.type)}} · 通过得{{(p.currentVersion||p.scheduledVersion||p.draftVersion)?.awardPoints??'—'}}积分</text><text v-if="(p.currentVersion||p.scheduledVersion||p.draftVersion)?.weekdays" class="caption">{{(p.currentVersion||p.scheduledVersion||p.draftVersion)!.weekdays!.map(d=>weekdays[d-1]).join('、')}}</text><text v-if="p.type==='CHALLENGE'" class="caption">{{dateTime((p.currentVersion||p.scheduledVersion||p.draftVersion)?.startsAt)}} 至 {{dateTime((p.currentVersion||p.scheduledVersion||p.draftVersion)?.endsAt)}}</text><text v-if="p.scheduledVersion" class="notice section">有明天起生效的新约定</text></view><EmptyState v-if="!plans.length&&!loading" title="一起约定第一件小事" description="明确要做什么、完成标准和通过后的积分。"><button class="primary section" @tap="go('planEdit')">新建计划</button></EmptyState><LoadMore :has-more="hasMore" :loading="busy" @more="act(()=>loadPlans(true))"/></template>
<template v-else-if="page==='planEdit'&&!session.isFamilyReadOnly"><view class="tabs"><button :disabled="!!plan" :class="[{active:form.type==='ROUTINE'}, {'is-disabled':(!!plan)}]" @tap="form.type='ROUTINE'">重复的日常</button><button :disabled="!!plan" :class="[{active:form.type==='CHALLENGE'}, {'is-disabled':(!!plan)}]" @tap="form.type='CHALLENGE'">一次挑战</button></view><view class="field"><text class="field-label">计划名称</text><input class="input" v-model="form.title" maxlength="40" placeholder="例如：整理书包、跳绳"/></view><view class="field"><text class="field-label">完成说明（选填）</text><textarea class="textarea" v-model="form.description" maxlength="500" placeholder="一起说清楚怎么确认完成"/></view><view class="field"><text class="field-label">怎样算达标</text><picker :range="metrics.map(label)" :value="metrics.indexOf(form.metric)" @change="form.metric=metrics[Number($event.detail.value)]"><view class="select-control">{{label(form.metric)}}</view></picker></view><view v-if="form.metric!=='CHECK'" class="field"><text class="field-label">目标总量（{{unit(form.metric,form.unit)}}）</text><input class="input" v-model="form.targetValue" type="number"/><view v-if="form.metric==='COUNT'" class="tabs"><button :class="{active:form.unit==='REP'}" @tap="form.unit='REP'">次</button><button :class="{active:form.unit==='ITEM'}" @tap="form.unit='ITEM'">个</button></view></view><view class="field"><text class="field-label">通过后获得积分</text><input class="input" v-model="form.awardPoints" type="number"/><text class="caption">一次达标固定加分，超过目标也不会额外加分。目标是家庭约定，不是运动建议。</text></view><text class="field-label section">适用孩子（至少一人）</text><view class="chip-row"><button v-for="c in children" :key="c.id" class="chip" :class="{active:form.childIds.includes(c.id)}" @tap="toggleChild(c.id)">{{c.nickname}}</button></view><button v-if="!children.length" class="secondary full" @tap="go('childEdit')">先添加孩子</button><template v-if="form.type==='ROUTINE'"><text class="field-label section">每周安排</text><view class="chip-row"><button v-for="(d,i) in weekdays" :key="d" class="chip" :class="{active:form.weekdays.includes(i+1)}" @tap="toggleDay(i+1)">{{d}}</button></view><view v-if="!plan||plan.lifecycle==='DRAFT'" class="field"><text class="field-label">开始时间</text><view class="tabs"><button :class="{active:startPolicy==='TOMORROW'}" @tap="startPolicy='TOMORROW'">明天开始</button><button :class="{active:startPolicy==='TODAY'}" @tap="startPolicy='TODAY'">今天从发布后开始</button></view></view><view v-else class="notice">修改从明天00:00生效，今天仍按原约定。</view></template><template v-else><view class="field"><text class="field-label">开始时间（北京时间）</text><view class="button-row"><picker mode="date" :value="form.startDate" @change="form.startDate=$event.detail.value"><view class="select-control">{{form.startDate}}</view></picker><picker mode="time" :value="form.startTime" @change="form.startTime=$event.detail.value"><view class="select-control">{{form.startTime}}</view></picker></view></view><view class="field"><text class="field-label">结束时间（北京时间）</text><view class="button-row"><picker mode="date" :value="form.endDate" @change="form.endDate=$event.detail.value"><view class="select-control">{{form.endDate}}</view></picker><picker mode="time" :value="form.endTime" @change="form.endTime=$event.detail.value"><view class="select-control">{{form.endTime}}</view></picker></view></view><view class="notice">发布后目标、积分、孩子和窗口冻结。修改要求需复制成新挑战。</view></template><view class="hero section"><text class="card-title">确认这份家庭约定</text><text class="hero-copy">{{form.title||'计划名称'}} · {{form.childIds.length}}位孩子 · {{form.metric==='CHECK'?'完成即可':`${form.targetValue||'—'}${unit(form.metric,form.unit)}`}} · 通过得{{form.awardPoints||'—'}}积分</text></view><view class="button-stack"><button :class="{'is-disabled':(busy)}" class="primary" :loading="busy" :disabled="busy" @tap="savePlan(true)">{{plan&&plan.lifecycle!=='DRAFT'?'保存明日起的新约定':'保存并发布'}}</button><button :class="{'is-disabled':(busy)}" v-if="!plan||plan.lifecycle==='DRAFT'" class="secondary" :disabled="busy" @tap="savePlan(false)">保存草稿</button></view></template>
<template v-else-if="page==='plan'&&plan"><view class="hero"><StatusPill :status="plan.currentVersion?.active===false?'PAUSED':plan.lifecycle"/><text class="page-title section">{{(plan.currentVersion||plan.scheduledVersion||plan.draftVersion)?.title||plan.title}}</text><text class="hero-copy">{{(plan.currentVersion||plan.scheduledVersion||plan.draftVersion)?.description}}</text><text class="points section">通过后获得{{(plan.currentVersion||plan.scheduledVersion||plan.draftVersion)?.awardPoints}}积分</text><text v-if="(plan.currentVersion||plan.scheduledVersion||plan.draftVersion)?.metric!=='CHECK'" class="caption">目标{{(plan.currentVersion||plan.scheduledVersion||plan.draftVersion)?.targetValue}}{{unit((plan.currentVersion||plan.scheduledVersion||plan.draftVersion)?.metric||'',(plan.currentVersion||plan.scheduledVersion||plan.draftVersion)?.unit)}}</text><text v-if="plan.type==='CHALLENGE'" class="caption">{{dateTime((plan.currentVersion||plan.scheduledVersion||plan.draftVersion)?.startsAt)}} 至 {{dateTime((plan.currentVersion||plan.scheduledVersion||plan.draftVersion)?.endsAt)}}</text></view><view v-if="plan.scheduledVersion" class="notice"><text>明天起{{plan.scheduledVersion.active?'生效':'暂停'}}：{{plan.scheduledVersion.title}} · {{plan.scheduledVersion.targetValue||'完成即可'}} · {{plan.scheduledVersion.awardPoints}}积分。今天实例不改变。</text></view><view v-if="plan.type==='ROUTINE'" class="field"><text class="field-label">查看哪一天的完成情况</text><picker mode="date" :value="date" @change="date=$event.detail.value;act(()=>loadOccurrences())"><view class="select-control">{{date}}</view></picker></view><view v-if="date>businessDate()" class="notice">未来日期是安排预览，不能审核或提前记录完成。</view><view v-for="o in occurrences" :key="o.id" class="card" @tap="date<=businessDate()&&go('occurrence',{id:o.id})"><view class="row between"><text>{{o.child?.nickname||o.childNickname||children.find(c=>c.id===o.childId)?.nickname||'孩子'}}</text><StatusPill :status="o.displayState||o.status"/></view><text class="caption">{{o.snapshot?.title}} · {{o.businessDate||'完整挑战周期'}}</text></view><EmptyState v-if="!occurrences.length&&!loading" title="这一天没有适用记录" description="只为真实被安排的日期记录，不补孩子加入前的任务。"/><LoadMore :has-more="hasMore" :loading="busy" @more="act(()=>loadOccurrences(true))"/><view v-if="!session.isFamilyReadOnly" class="button-stack"><button v-if="plan.lifecycle==='DRAFT'||plan.type==='ROUTINE'" class="secondary" @tap="go('planEdit',{id:plan.id})">{{plan.lifecycle==='DRAFT'?'编辑草稿':'编辑明日起的日常'}}</button><button v-if="plan.lifecycle==='DRAFT'" class="primary" @tap="planAction('publish')">发布这份约定</button><button v-if="plan.type==='ROUTINE'&&plan.lifecycle!=='DRAFT'" class="secondary" @tap="planAction((plan.scheduledVersion||plan.currentVersion)?.active===false?'resume':'pause')">{{(plan.scheduledVersion||plan.currentVersion)?.active===false?'明天恢复':'明天暂停'}}</button></view><view v-if="!session.isFamilyReadOnly&&plan.type==='CHALLENGE'&&plan.lifecycle!=='DRAFT'" class="card section"><text class="card-title">展示说明</text><textarea class="textarea section" v-model="displayDescription" maxlength="500"/><text class="caption">不能借展示说明改变原完成标准。</text><button class="secondary full section" @tap="saveDescription">保存展示说明</button><view v-if="!plan.stoppedAt" class="field"><text class="field-label">停止原因</text><textarea class="textarea" v-model="reason" maxlength="200"/><button class="danger-button full" @tap="planAction('stop')">停止这次挑战</button></view></view><view v-if="!session.isFamilyReadOnly" class="card section"><text class="card-title">复制为一份新约定</text><input class="input section" v-model="copyTitle" maxlength="40"/><button class="secondary full section" @tap="planAction('copy')">创建新草稿</button></view><text class="section-title section">版本历史</text><view v-for="v in versions" :key="v.id||v.revision" class="card section"><text>版本{{v.revision}} · {{v.title}}</text><text class="caption">生效 {{dateTime(v.effectiveFrom)}} · {{v.awardPoints}}积分</text></view></template>
<template v-else-if="['occurrence','activity'].includes(page)&&occurrence&&snapshot"><StatusPill :status="occurrence.displayState||occurrence.status"/><text class="page-title section">{{snapshot.title}}</text><text class="caption section">{{occurrence.businessDate||'一次挑战'}} · {{dateTime(occurrence.startsAt)}} 至 {{dateTime(occurrence.endsAt)}}</text><view class="notice section">{{snapshot.metric==='CHECK'?'按要求完成':`达到${snapshot.targetValue}${unit(snapshot.metric,snapshot.unit)}`}}，通过后获得{{snapshot.awardPoints}}积分。超额完成不会额外加分。</view><text v-if="snapshot.description" class="body-copy">{{snapshot.description}}</text><view v-if="occurrence.status==='NEEDS_CHANGES'" class="notice warning section">请查看家长的补充原因，并在{{dateTime(occurrence.supplementUntil)}}前补充。</view>
<template v-if="!session.isFamilyReadOnly&&(childPage?editable:['OPEN','NEEDS_CHANGES'].includes(occurrence.status))"><view v-if="snapshot.metric==='CHECK'" class="check-row section" @tap="checked=!checked;saved=false"><checkbox :checked="checked" color="#176b5b"/><text>我已经按约定完成</text></view><view v-else class="field"><text class="field-label">这次总共完成多少（{{unit(snapshot.metric,snapshot.unit)}}）</text><input class="input number-input" v-model="count" type="number" @input="saved=false"/><text class="caption">填写本次实例的总完成量，不会把多次输入相加。</text></view><view v-if="!childPage" class="field"><text class="field-label">实际完成时间（北京时间）</text><view class="button-row"><picker mode="date" :value="completedDate" :start="businessDate(occurrence.startsAt)" :end="businessDate(occurrence.endsAt)" @change="completedDate=$event.detail.value"><view class="select-control">{{completedDate}}</view></picker><picker mode="time" :value="completedTime" @change="completedTime=$event.detail.value"><view class="select-control">{{completedTime}}</view></picker></view><text class="caption">只记录真实发生且在原窗口内的完成；日常含今天可补记8个日期，挑战截止后7×24小时内可补记。</text></view><view class="field"><text class="field-label">完成说明（选填）</text><textarea class="textarea" v-model="note" maxlength="200" @input="saved=false"/></view><MediaUploader v-model="photos" :scope="{purpose:'COMPLETION_EVIDENCE',familyId:session.view?.familyId,childId:occurrence.childId,occurrenceId:occurrence.id}"/><view class="button-stack"><button :class="{'is-disabled':(busy||photos.some(p=>p.status!=='READY'))}" class="primary" :loading="busy" :disabled="busy||photos.some(p=>p.status!=='READY')" @tap="submit(!childPage)">{{childPage?'提交给家长':`记录完成并加${snapshot.awardPoints}积分`}}</button><button :class="{'is-disabled':(busy)}" v-if="!childPage" class="secondary" :disabled="busy" @tap="submit(false)">代孩子提交，等待审核</button><button :class="{'is-disabled':(busy)}" class="secondary" :disabled="busy" @tap="saveDraft">保存草稿</button></view><text class="caption section">{{saved?'草稿已保存到服务端，未提交和发分。':'文字和数量自动保存在本机24小时；保存草稿后可跨设备查看。照片处理完成前请留在此页。'}}</text></template>
<template v-if="!childPage&&occurrence.status==='SUBMITTED'"><view class="button-stack"><button :class="{'is-disabled':(busy)}" class="primary" :loading="busy" :disabled="busy" @tap="review('APPROVE')">通过并加{{snapshot.awardPoints}}积分</button><button class="secondary" @tap="action='RETURN';reason=''">请孩子补充</button></view></template><button v-if="!childPage&&['OPEN','SUBMITTED','NEEDS_CHANGES'].includes(occurrence.status)" class="text-button full section" @tap="action='EXEMPT';reason=''">{{occurrence.type==='ROUTINE'?'今天休息，设为免做':'本次免做'}}</button><view v-if="action" class="card section"><text class="card-title">{{action==='RETURN'?'请补充的原因':'本次免做的原因'}}</text><textarea class="textarea section" v-model="reason" maxlength="200"/><text class="caption section">{{action==='RETURN'?'补充期限取原截止与本次退回后24小时中较晚者。':'不发分、不扣分，不计入应完成数；首发不支持恢复。'}}</text><button :class="{'is-disabled':(busy)}" class="primary full section" :loading="busy" :disabled="busy" @tap="review(action as 'RETURN'|'EXEMPT')">确认{{action==='RETURN'?'请孩子补充':'本次免做'}}</button><button class="text-button full" @tap="action=''">返回</button></view><view v-if="childPage&&!editable&&occurrence.status==='OPEN'" class="notice warning section">当前还未开放或已经截止，请家长帮忙看看。</view><button v-if="!childPage&&occurrence.status==='APPROVED'" class="secondary full section" @tap="go('ledger',{childId:occurrence.childId})">查看积分记录，必要时完整纠错</button>
<view v-if="occurrence.latestSubmission" class="section"><text class="section-title">提交与处理记录</text><view v-for="s in occurrence.submissions||[occurrence.latestSubmission]" :key="s.id" class="card section"><text class="card-title">第{{s.sequence}}次提交 · {{s.checked?'已完成':`${s.actualValue??'—'}${unit(snapshot.metric,snapshot.unit)}`}}</text><text class="body-copy">{{s.note||'没有填写说明'}}</text><text class="caption">提交 {{dateTime(s.submittedAt)}} · {{s.actorMode==='GUARDIAN'?'家长代录':'孩子提交'}}</text><text v-if="s.completedAt" class="caption">实际完成 {{dateTime(s.completedAt)}} · 记录 {{dateTime(s.recordedAt)}}</text><view class="media-grid"><view v-for="m in s.media" :key="m.id" @tap="m.status!=='DELETED'&&showPhotos(s)"><PrivateImage v-if="m.status!=='DELETED'" :media-id="m.id" size="180rpx"/><text v-else class="caption">照片已按保存期限清理</text></view></view><view v-for="(r,index) in occurrence.reviewHistory?.filter(r=>r.submissionId===s.id)||[]" :key="r.id||index" class="timeline-item"><text class="timeline-title">{{(r.action||r.decision)==='APPROVE'?'已通过':(r.action||r.decision)==='RETURN'?'请补充':label(r.action||r.decision)}}</text><text class="body-copy">{{r.reason}}</text><text class="caption">{{displayOperator(r.operatorSummary||r.actor)}} · {{dateTime(r.reviewedAt||r.createdAt)}}</text></view></view></view>
</template></AppShell></template>
